CREATE TYPE "ExpenseTransactionType" AS ENUM ('PROJECT_EXPENSE','OFFICE_EXPENSE','OTHER_INCOME','REIMBURSEMENT'); CREATE TYPE "ExpenseTransactionStatus" AS ENUM ('DRAFT','PENDING_APPROVAL','APPROVED','POSTED','REJECTED','CANCELLED','REVERSED'); CREATE TYPE "ExpenseCategoryScope" AS ENUM ('EXPENSE','INCOME','BOTH'); CREATE TYPE "RecurringFrequency" AS ENUM ('WEEKLY','MONTHLY','QUARTERLY','YEARLY');
CREATE TABLE "expense_categories" ("id" UUID PRIMARY KEY,"companyId" UUID NOT NULL,"name" VARCHAR(160) NOT NULL,"scope" "ExpenseCategoryScope" NOT NULL,"defaultLedgerAccountId" UUID NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT TRUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("companyId","id"),UNIQUE("companyId","name"));
CREATE TABLE "expense_transactions" ("id" UUID PRIMARY KEY,"companyId" UUID NOT NULL,"branchId" UUID NOT NULL,"projectId" UUID,"categoryId" UUID NOT NULL,"type" "ExpenseTransactionType" NOT NULL,"status" "ExpenseTransactionStatus" NOT NULL DEFAULT 'DRAFT',"transactionNumber" VARCHAR(100) NOT NULL,"transactionDate" DATE NOT NULL,"taxableAmount" DECIMAL(18,2) NOT NULL,"taxRate" DECIMAL(7,4) NOT NULL DEFAULT 0,"taxAmount" DECIMAL(18,2) NOT NULL DEFAULT 0,"totalAmount" DECIMAL(18,2) NOT NULL,"moneyAccountId" UUID,"occurrenceKey" VARCHAR(160),"journalEntryId" UUID,"approvedById" UUID,"approvedAt" TIMESTAMP(3),"createdById" UUID NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("companyId","id"),UNIQUE("companyId","occurrenceKey"),UNIQUE("companyId","journalEntryId"));
CREATE TABLE "recurring_expense_templates" ("id" UUID PRIMARY KEY,"companyId" UUID NOT NULL,"branchId" UUID NOT NULL,"projectId" UUID,"categoryId" UUID NOT NULL,"frequency" "RecurringFrequency" NOT NULL,"nextDueDate" DATE NOT NULL,"amount" DECIMAL(18,2) NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT TRUE,"createdById" UUID NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("companyId","id"));
CREATE TABLE "expense_attachments" ("id" UUID PRIMARY KEY,"companyId" UUID NOT NULL,"expenseId" UUID NOT NULL,"storageKey" VARCHAR(512) NOT NULL,"displayName" VARCHAR(240) NOT NULL,"mimeType" VARCHAR(120) NOT NULL,"sizeBytes" INTEGER NOT NULL,"uploadedById" UUID NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("companyId","id"),UNIQUE("companyId","storageKey"));
ALTER TABLE "expense_transactions" ADD CONSTRAINT "expense_project_company_fkey" FOREIGN KEY ("companyId","projectId") REFERENCES "projects"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT; ALTER TABLE "expense_transactions" ADD CONSTRAINT "expense_category_company_fkey" FOREIGN KEY ("companyId","categoryId") REFERENCES "expense_categories"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT; ALTER TABLE "expense_attachments" ADD CONSTRAINT "attachment_expense_company_fkey" FOREIGN KEY ("companyId","expenseId") REFERENCES "expense_transactions"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT;
